with j as (select * from jsonb_to_recordset($law7d0006$[{"code_id":"APK_RF","article_number":"189","version_date":"2002-07-24","article_text":"1. Дела, возникающие из административных и иных публичных правоотношений, рассматриваются по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными в настоящем разделе, если иные правила административного судопроизводства не предусмотрены федеральным законом.","article_title":"Статья 189. Порядок рассмотрения дел, возникающих из административных и иных публичных правоотношений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8cedee9da6e86f75496a0f485498d116a3afda609fbe29cec9554199307f8542"},{"code_id":"APK_RF","article_number":"19","version_date":"2002-07-24","article_text":"1. Арбитражные заседатели могут быть привлечены к рассмотрению дел в арбитражных судах первой инстанции в соответствии с настоящим Кодексом и другими федеральными законами по ходатайству стороны в связи с особой сложностью дела и (или) необходимостью использования специальных знаний в сфере экономики, финансов, управления.\n\n2. Ходатайство о рассмотрении дела с участием арбитражных заседателей должно содержать обоснование особой сложности дела и (или) необходимости использования специальных знаний и может быть заявлено стороной не позднее чем за один месяц до начала судебного разбирательства, в том числе при каждом новом рассмотрении дела.\n\nСуд обязан разъяснить сторонам их право заявлять такое ходатайство в определении о принятии искового заявления к производству суда и при подготовке дела к судебному разбирательству.\n\n3. Ходатайство о рассмотрении дела с участием арбитражных заседателей разрешается арбитражным судом в порядке, установленном статьей 159 настоящего Кодекса.\n\nВ случае, если ходатайство о рассмотрении дела с участием арбитражных заседателей удовлетворено, кандидатуры арбитражных заседателей определяются из списка арбитражных заседателей, утвержденного в установленном федеральным законом порядке, с учетом их специализации, путем случайной выборки с использованием автоматизированной информационной системы или иным способом, применяемым в арбитражном суде для формирования состава суда.\n\n4. Наличие случая, предусмотренного частями 3 и 4 статьи 18 настоящего Кодекса, является основанием для замены арбитражного заседателя. В этом случае другая кандидатура арбитражного заседателя определяется в порядке, установленном частью 3 настоящей статьи.\n\nЕсли после отвода одного или нескольких арбитражных заседателей невозможно сформировать состав суда для рассмотрения дела с участием арбитражных заседателей, указанное дело рассматривается судьей единолично.\n\nВ случае неявки в судебное заседание одного или двух арбитражных заседателей дело может быть рассмотрено судьей единолично, если стороны или их представители присутствуют в данном судебном заседании и не возражают против рассмотрения дела судьей единолично.\n\nЕсли хотя бы одна из сторон возражает против рассмотрения дела судьей единолично, суд объявляет перерыв в судебном заседании или откладывает судебное разбирательство. Если проведение нового судебного заседания невозможно вследствие неявки в судебное заседание одного или двух арбитражных заседателей, суд по ходатайству одной из сторон вправе вынести определение о рассмотрении дела судьей единолично и открыть судебное заседание в первой инстанции.\n\n5. При рассмотрении дела арбитражные заседатели пользуются правами и несут обязанности судьи.\n\n6. Судья и арбитражный заседатель при рассмотрении дела, разрешении всех вопросов, возникающих при рассмотрении дела и принятии судебных актов, пользуются равными процессуальными правами.\n\n7. Арбитражный заседатель не может быть председательствующим в судебном заседании.\n\n(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 19. Привлечение к рассмотрению дел арбитражных заседателей","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24483ab7a2ef5527ab73e723109f16c0526283b2870dc33239bacad59022a0e8"},{"code_id":"APK_RF","article_number":"190","version_date":"2002-07-24","article_text":"1. Экономические споры, возникающие из административных и иных публичных правоотношений, могут быть урегулированы сторонами путем использования примирительных процедур по правилам, установленным в главе 15 настоящего Кодекса, поскольку иное не установлено настоящим Кодексом, другими законами и не вытекает из существа соответствующих правоотношений.\n\n2. В случаях, если до обращения в арбитражный суд с требованиями об оспаривании ненормативных правовых актов, решений и действий (бездействия) органов, осуществляющих публичные полномочия, и должностных лиц, о взыскании обязательных платежей и санкций стороны не использовали досудебное урегулирование спора, арбитражный суд вправе при согласии организации, индивидуального предпринимателя или гражданина в целях примирения сторон и уточнения фактических обстоятельств, снятия противоречий в позициях, в том числе путем проведения сверки взаимных расчетов, отложить судебное разбирательство в порядке, установленном настоящим Кодексом, предложив сторонам использовать примирительную процедуру, в том числе с участием судебного примирителя.\n\n3. Результатами примирения сторон по спорам, возникающим из административных и иных публичных правоотношений, могут быть, в частности:\n\n1) признание обстоятельств дела, соглашение сторон по обстоятельствам дела;\n\n2) соглашение сторон, содержащее квалификацию сделки, совершенной лицом, участвующим в деле, или статуса и характера деятельности этого лица;\n\n3) частичный или полный отказ от тр\n\nебований, частичное или полное признание требований, в том числе вследствие достижения сторонами соглашения об оценке обстоятельств в целом или их отдельных частей;\n\n4) мировое соглашение, если к полномочиям соответствующего административного органа, участвующего в деле, федеральным законом отнесено заключение мировых соглашений.\n\n(Статья в редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n(Наименование в редакции Федерального закона от 15.02.2016 № 18-ФЗ)","article_title":"Статья 190. Примирение сторон по спорам, возникающим из административных и иных публичных правоотношений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ed53bdf90a4d14766d16936c1db4f50d44ae4df7d8b8c2d572ec89bedf3c2258"},{"code_id":"APK_RF","article_number":"191","version_date":"2002-07-24","article_text":"1. Дела об оспаривании нормативных правовых актов федеральных органов исполнительной власти в сфере патентных прав и прав на селекционные достижения, права на топологии интегральных микросхем, права на секреты производства (ноу-хау), права на средства индивидуализации юридических лиц, товаров, работ, услуг и предприятий, права использования результатов интеллектуальной деятельности в составе единой технологии (далее в настоящей главе - нормативный правовой акт) рассматриваются Судом по интеллектуальным правам по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными в настоящей главе.\n\n2. Производство по делам об оспаривании нормативных правовых актов возбуждается на основании заявлений заинтересованных лиц, обратившихся с требованием о признании такого оспариваемого акта недействующим.\n\n(Статья в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 191. Порядок рассмотрения дел об оспаривании нормативных правовых актов Судом по интеллектуальным правам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dddb9f06b74a746b2b865f639188ef5ddb3bef75156c618299664a6e235ae45d"},{"code_id":"APK_RF","article_number":"192","version_date":"2002-07-24","article_text":"1. Граждане, организации и иные лица вправе обратиться в Суд по интеллектуальным правам с заявлениями о признании недействующими нормативных правовых актов, если полагают, что такой оспариваемый нормативный правовой акт или отдельные его положения не соответствуют закону или иному нормативному правовому акту, имеющим большую юридическую силу, и нарушают их права и законные интересы.\n\n2. Прокурор, а также государственные органы, органы местного самоуправления, иные органы вправе обратиться в Суд по интеллектуальным правам в случаях, предусмотренных настоящим Кодексом, с заявлениями о признании нормативных правовых актов недействующими, если полагают, что такой оспариваемый акт или отдельные его положения не соответствуют закону или иному нормативному правовому акту, имеющим большую юридическую силу, и нарушают права и законные интересы граждан, организаций, иных лиц.\n\n3. Обращение заинтересованного лица в вышестоящий в порядке подчиненности орган или к должностному лицу не является обязательным условием для подачи заявления в Суд по интеллектуальным правам, если федеральным законом не установлено иное.\n\n(Статья в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 192. Право на обращение в Суд по интеллектуальным правам с заявлением о признании нормативного правового акта недействующим","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"483fa622213eb5737276eff51cf0aac822d917e69c0994e0d15b22711cb3183a"},{"code_id":"APK_RF","article_number":"193","version_date":"2002-07-24","article_text":"1. Заявление о признании нормативного правового акта недействующим должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2, частью 3 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) наименование федерального органа исполнительной власти, принявшего оспариваемый нормативный правовой акт;\n\n2) название, номер, дата принятия, источник опубликования и иные данные об оспариваемом нормативном правовом акте;\n\n3) права и законные интересы заявителя, которые, по его мнению, нарушаются оспариваемым актом или его отдельными положениями;\n\n4) название нормативного правового акта, который имеет большую юридическую силу и на соответствие которому надлежит проверить оспариваемый акт или его отдельные положения;\n\n5) требование заявителя о признании оспариваемого акта недействующим;\n\n6) перечень прилагаемых документов.\n\n2. К заявлению прилагаются документы, указанные в пунктах 1 - 5 статьи 126 настоящего Кодекса, а также текст оспариваемого нормативного правового акта.\n\n3. Подача заявления в Суд по интеллектуальным правам не приостанавливает действие оспариваемого нормативного правового акта.\n\n(Статья в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 193. Требования к заявлению о признании нормативного правового акта недействующим","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7cc50ad35cce141285de99e02f58871340c6678d665c533539a7e9d672f3cd85"},{"code_id":"APK_RF","article_number":"194","version_date":"2002-07-24","article_text":"1. Дело об оспаривании нормативного правового акта рассматривается коллегиальным составом судей в срок, не превышающий трех месяцев со дня поступления заявления в суд, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу.\n\n2. Суд по интеллектуальным правам извещает о времени и месте судебного заседания заявителя, орган, принявший оспариваемый нормативный правовой акт, а также иных заинтересованных лиц. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения дела, если суд не признал их явку обязательной.\n\n3. Суд по интеллектуальным правам может признать обязательной явку в судебное заседание представителей государственных органов, органов местного самоуправления, иных органов, должностных лиц, принявших оспариваемый нормативный правовой акт, и вызвать их в судебное заседание для дачи объяснений.\n\nНеявка указанных лиц, вызванных в судебное заседание, является основанием для наложения штрафа в порядке и в размерах, которые установлены в главе 11 настоящего Кодекса.\n\n4. При рассмотрении дел об оспаривании нормативных правовых актов Суд по интеллектуальным правам в судебном заседании осуществляет проверку оспариваемого акта или его отдельного положения, устанавливает соответствие его федеральному конституционному закону, федеральному закону и иному нормативному правовому акту, имеющим большую юридическую силу, а также полномочия органа или лица, принявших оспариваемый нормативный правовой акт.\n\n5. Суд по интеллектуальным правам не связан доводами, содержащимися в заявлении об оспаривании нормативного правового акта, и проверяет оспариваемое положение в полном объеме.\n\n6. Обязанность доказывания соответствия оспариваемого нормативного правового акта федеральному конституционному закону, федеральному закону и иному нормативному правовому акту, имеющим большую юридическую силу, наличия у органа или должностного лица надлежащих полномочий на принятие оспариваемого акта, а также обстоятельств, послуживших основанием для его принятия, возлагается на орган, должностное лицо, которые приняли оспариваемый акт.\n\n7. В случае, если имеется вступившее в законную силу решение арбитражного суда или суда общей юрисдикции по ранее рассмотренному делу, проверившего по тем же основаниям соответствие оспариваемого нормативного правового акта иному нормативному правовому акту, имеющему большую юридическую силу, Суд по интеллектуальным правам прекращает производство по делу.\n\n8. Отказ заинтересованного лица, обратившегося в Суд по интеллектуальным правам с заявлением об оспаривании нормативного правового акта, от своего требования, признание требования органом или лицом, которые приняли оспариваемый акт, не препятствуют рассмотрению Судом по интеллектуальным правам дела по существу.\n\n(Статья в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 194. Судебное разбирательство по делу об оспаривании нормативного правового акта","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1cc04cb32b81b37b5fc3e09f490364d752d48d15e19519852e1cc9aa37afc7bd"},{"code_id":"APK_RF","article_number":"195","version_date":"2002-07-24","article_text":"1. Решение по делу об оспаривании нормативного правового акта принимается Судом по интеллектуальным правам по правилам, установленным в главе 20 настоящего Кодекса.\n\n2. По результатам рассмотрения дела об оспаривании нормативного правового акта Суд по интеллектуальным правам принимает одно из решений:\n\n1) о признании оспариваемого акта или отдельных его положений соответствующими иному нормативному правовому акту, имеющему большую юридическую силу;\n\n2) о признании оспариваемого нормативного правового акта или отдельных его положений не соответствующими иному нормативному правовому акту, имеющему большую юридическую силу, и не действующими полностью или в части.\n\n3. В резолютивной части решения по делу об оспаривании нормативного правового акта должны содержаться:\n\n1) наименование органа или лица, принявших оспариваемый акт, его название, номер, дата принятия акта;\n\n2) название нормативного правового акта, который имеет большую юридическую силу и на соответствие которому проверен оспариваемый акт;\n\n3) указание на признание оспариваемого акта соответствующим нормативному правовому акту, имеющему большую юридическую силу, и на отказ в удовлетворении заявленного требования или на признание оспариваемого акта не соответствующим нормативному правовому акту, имеющему большую юридическую силу, и не действующим полностью или в части.\n\n4. Решение Суда по интеллектуальным правам по делу об оспаривании нормативного правового акта вступает в законную силу немедленно после его принятия.\n\n5. Нормативный правовой акт или отдельные его положения, признанные Судом по интеллектуальным правам недействующими, не подлежат применению с момента вступления в законную силу решения суда и должны быть приведены органом или лицом, принявшими оспариваемый акт, в соответствие с законом или иным нормативным правовым актом, имеющими большую юридическую силу.\n\n6. Копии решения Суда по интеллектуальным правам в срок, не превышающий десяти дней со дня его принятия, направляются лицам, участвующим в деле.\n\n7. Вступившее в законную силу решение Суда по интеллектуальным правам по делу об оспаривании нормативного правового акта может быть обжаловано по правилам, установленным настоящим Кодексом.\n\n(Статья в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 195. Решение суда по делу об оспаривании нормативного правового акта","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a27c2010e227629bce6a42ac11885fcdc7e9a05549cb3906f4eef79c3e911d18"},{"code_id":"APK_RF","article_number":"195.1","version_date":"2002-07-24","article_text":"1. Дела об оспаривании актов федеральных органов исполнительной власти в сфере патентных прав и прав на селекционные достижения, права на топологии интегральных микросхем, права на секреты производства (ноу-хау), права на средства индивидуализации юридических лиц, товаров, работ, услуг и предприятий, права использования результатов интеллектуальной деятельности в составе единой технологии, содержащих разъяснения законодательства и обладающих нормативными свойствами (далее - акты, обладающие нормативными свойствами), рассматриваются Судом по интеллектуальным правам по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными настоящей главой и определенными в настоящей статье.\n\n2. С заявлением о признании недействующим акта, обладающего нормативными свойствами, вправе обратиться лица, указанные в частях 1 и 2 статьи 192 настоящего Кодекса, если они полагают, что такой акт обладает нормативными свойствами и по своему содержанию не соответствует разъясняемым им нормативным положениям.\n\n3. При рассмотрении дел об оспаривании актов, обладающих нормативными свойствами, Суд по интеллектуальным правам устанавливает, обладает ли оспариваемый акт нормативными свойствами, позволяющими применить его неоднократно в качестве общеобязательного предписания в отношении неопределенного круга лиц, и соответствуют ли положения оспариваемого акта разъясняемым им нормативным положениям.\n\n4. Обязанность доказывания соответствия положений оспариваемого акта разъясняемым им нормативным положениям возлагается на орган или должностное лицо, которые приняли оспариваемый акт.\n\n5. По результатам рассмотрения дела об оспаривании акта, обладающего нормативными свойствами, Суд по интеллектуальным правам принимает одно из следующих решений:\n\n1) о признании оспариваемого акта полностью или в части не обладающим нормативными свойствами и соответствующим разъясняемым им нормативным положениям;\n\n2) о признании оспариваемого акта полностью или в части не соответствующим разъясняемым им нормативным положениям, устанавливающим не предусмотренные разъясняемыми нормативными положениями общеобязательные правила, распространяющиеся на неопределенный круг лиц и рассчитанные на неоднократное применение, и о признании этого акта не действующим полностью или в части.\n\n(Дополнение статьей - Федеральный закон от 15.02.2016 № 18-ФЗ)","article_title":"Статья 195.1. Рассмотрение дел об оспаривании актов, содержащих разъяснения законодательства и обладающих нормативными свойствами","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"42a2849010371b85a3336a2581f1dcea7b44a80d6ab8a3617795c120d6d1a116"},{"code_id":"APK_RF","article_number":"196","version_date":"2002-07-24","article_text":"Вступившее в законную силу решение Суда по интеллектуальным правам по делу об оспаривании нормативного правового акта или по делу об оспаривании акта, обладающего нормативными свойствами, направляется Судом по интеллектуальным правам в официальные издания федеральных органов исполнительной власти и другие официальные издания, в которых был опубликован оспариваемый акт, и подлежит незамедлительному опубликованию указанными изданиями. (В редакции Федерального закона от 17.04.2017 № 76-ФЗ)\n\n(Статья в редакции Федеральный закон от 15.02.2016 № 18-ФЗ)\n\n(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 196. Опубликование решения Суда по интеллектуальным правам по делу об оспаривании нормативного правового акта или по делу об оспаривании акта, обладающего нормативными свойствами","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f136508057e4c0878798285a248fc7e2cfb0ff57a8232b8fbab00b3e91ed397d"},{"code_id":"APK_RF","article_number":"197","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 197. Порядок рассмотрения дел об оспаривании ненормативных правовых актов, решений и действий (бездействия) государственных органов, органов местного самоуправления, иных органов, организаций, наделенных федеральным законом отдельными государственными или иными публичными полномочиями, должностных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a953dd3cf2bc708c849f1f130426d87a16b81bc88b6c9cc7eb7e1e395c35c60"},{"code_id":"APK_RF","article_number":"199","version_date":"2002-07-24","article_text":"1. Заявление о признании ненормативного правового акта недействительным, решений и действий (бездействия) незаконными должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2, частью 3 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) наименование органа или лица, которые приняли оспариваемый акт, решение, совершили оспариваемые действия (бездействие);\n\n2) название, номер, дата принятия оспариваемого акта, решения, время совершения действий;\n\n3) права и законные интересы, которые, по мнению заявителя, нарушаются оспариваемым актом, решением и действием (бездействием);\n\n4) законы и иные нормативные правовые акты, которым, по мнению заявителя, не соответствуют оспариваемый акт, решение и действие (бездействие);\n\n5) требование заявителя о признании ненормативного правового акта недействительным, решений и действий (бездействия) незаконными.\n\nВ заявлении об оспаривании решений и действий (бездействия) должностного лица службы судебных приставов должны быть также указаны сведения об исполнительном документе, в связи с исполнением которого оспариваются решения и действия (бездействие) указанного должностного лица. (В редакции Федерального закона от 02.10.2007 № 225-ФЗ)\n\n2. К заявлению прилагаются документы, указанные в статье 126 настоящего Кодекса, а также текст оспариваемого акта, решения.\n\nК заявлению об оспаривании решений и действий (бездействия) должностного лица службы судебных приставов прилагаются, кроме того, уведомление о вручении или иные документы, подтверждающие направление копии заявления и необходимых доказательств указанному должностному лицу и другой стороне исполнительного производства. (В редакции Федерального закона от 02.10.2007 № 225-ФЗ)","article_title":"Статья 199. Требования к заявлению о признании ненормативного правового акта недействительным, решений и действий (бездействия) незаконными","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a32e1b7c3b06dc7b35203d0664d109d68b20b79bd4407290dc454863116f94e"},{"code_id":"APK_RF","article_number":"2","version_date":"2002-07-24","article_text":"Задачами судопроизводства в арбитражных судах являются:\n\n1) защита нарушенных или оспариваемых прав и законных интересов лиц, осуществляющих предпринимательскую и иную экономическую деятельность, а также прав и законных интересов Российской Федерации, субъектов Российской Федерации, муниципальных образований в сфере предпринимательской и иной экономической деятельности, органов государственной власти Российской Федерации, органов государственной власти субъектов Российской Федерации, органов местного самоуправления, иных органов, должностных лиц в указанной сфере;\n\n2) обеспечение доступности правосудия в сфере предпринимательской и иной экономической деятельности;\n\n3) справедливое публичное судебное разбирательство в разумный срок независимым и беспристрастным судом; (В редакции Федерального закона от 30.04.2010 № 69-ФЗ)\n\n4) укрепление законности и предупреждение правонарушений в сфере предпринимательской и иной экономической деятельности;\n\n5) формирование уважительного отношения к закону и суду;\n\n6) содействие становлению и развитию партнерских деловых отношений, мирному урегулированию споров, формированию обычаев и этики делового оборота. (В редакции Федерального закона от 26.07.2019 № 197-ФЗ)","article_title":"Статья 2. Задачи судопроизводства в арбитражных судах","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8cd701b4b761ab88947dbd7ddf5ffd63c0b0efb1f8f4d09d4bdb154c429c4093"},{"code_id":"APK_RF","article_number":"20","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\n1. Вопросы, возникающие при рассмотрении дела судом в коллегиальном составе, разрешаются судьями большинством голосов. Никто из судей не вправе воздержаться от голосования. Судья - председательствующий в заседании - голосует последним.\n\n2. Судья, несогласный с мнением большинства судей, голосовавших за принятие судебного акта, обязан подписать этот судебный акт и вправе изложить в письменной форме свое особое мнение.\n\nСудья, голосовавший за принятый судебный акт по существу рассматриваемого судом вопроса, но оставшийся в меньшинстве при голосовании по какому-либо другому вопросу или по мотивировке принятого судебного акта, также вправе изложить в письменной форме свое особое мнение.\n\nПри изложении своего особого мнения судья не вправе сообщать кому бы то ни было сведения о содержании обсуждения при принятии судебного акта, о позиции отдельных судей, входивших в состав суда, и иным способом раскрывать тайну совещания судей.\n\nОсобое мнение судьи должно быть изготовлено в срок, не превышающий пяти дней со дня принятия решения по делу. Особое мнение судьи приобщается к материалам дела, но не оглашается.\n\n(Часть в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 20. Порядок разрешения вопросов судом в коллегиальном составе. Особое мнение судьи","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e2b2cf4ecf2d39148857eab4330d6e8e0f1aa55b414be24eed3dc7575a5b3e78"},{"code_id":"APK_RF","article_number":"200","version_date":"2002-07-24","article_text":"ений и действий (бездействия) органов, осуществляющих публичные полномочия, должностных лиц\n\n(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\nДела об оспаривании решений и действий (бездействия) должностного лица службы судебных приставов рассматриваются в срок, не превышающий десяти дней со дня поступления заявления в арбитражный суд, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу. Указанный срок может быть продлен на основании мотивированного заявления судьи, рассматривающего дело, председателем арбитражного суда, заместителем председателя арбитражного суда до трех месяцев в связи с особой сложностью дела, со значительным числом участников арбитражного процесса. (В редакции  федеральных законов от 02.10.2007 № 225-ФЗ, от 25.12.2023 № 667-ФЗ)\n\nДела об оспаривании решений органов местного самоуправления о сносе самовольных построек или об их приведении в соответствие с предельными параметрами разрешенного строительства, реконструкции объектов капитального строительства, установленными правилами землепользования и застройки, документацией по планировке территории, или обязательными требованиями к параметрам объектов капитального строительства, установленными федеральными законами, об оспаривании решений органов государственной власти или органов местного самоуправления о прекращении вещных прав на земельные участки (права пожизненного наследуемого владения, права постоянного (бессрочного) пользования) в связи с неисполнением обязанностей по сносу самовольной постройки или ее приведению в соответствие с указанными параметрами и требованиями рассматриваются в срок, не превышающий одного месяца со дня поступления соответствующего заявления в арбитражный суд, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу. (Дополнение абзацем - Федеральный закон от 03.08.2018 № 340-ФЗ)","article_title":"Статья 200. Судебное разбирательство по делам об оспаривании ненормативных правовых актов, реш","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d3c45c2cd312f4a1038cc4f242b20330ed02323d6cac12d36a1aaadf02566af8"},{"code_id":"APK_RF","article_number":"201","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\n1) наименование органа или лица, принявших оспариваемый акт, решение; название, номер, дата принятия оспариваемого акта, решения;\n\n2) название закона или иного нормативного правового акта, на соответствие которому проверены оспариваемый акт, решение;\n\n3) указание на признание оспариваемого акта недействительным или решения незаконным полностью или в части и обязанность устранить допущенные нарушения прав и законных интересов заявителя либо на отказ в удовлетворении требования заявителя полностью или в части.\n\n1) наименование органа или лица, совершивших оспариваемые действия (бездействие) и отказавших в совершении действий, принятии решений; сведения о действиях (бездействии), решениях;\n\n2) название закона или иного нормативного правового акта, на соответствие которым проверены оспариваемые действия (бездействие), решения;\n\n3) указание на признание оспариваемых действий (бездействия) незаконными и обязанность соответствующих органов, осуществляющих публичные полномочия, должностных лиц совершить определенные действия, принять решения или иным образом устранить допущенные нарушения прав и законных интересов заявителя в установленный судом срок либо на отказ в удовлетворении требования заявителя полностью или в части. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 201. Решение арбитражного суда по делу об оспаривании ненормативных правовых актов, решений и действий (бездействия) органов, осуществляющих публичные полномочия, должностных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"11651f5cc994222911bdacd0b4bebbd26dd6f876e94248a710386b0ff4f41efc"}]$law7d0006$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
